command:
/**
 * SVA example: Melee Attack (Advanced)
 * A configurable weapon swing from the selected token to every target, with optional
 * trail, impact and blood. Targets out of reach get a thrown weapon (with return) instead.
 *
 * Usage: select the attacker, target one or more tokens, run.
 * Hold SHIFT while clicking the macro to play it as a miss.
 * Edit CONFIG below to change the weapon, colours and options. Browse paths with SVA.ui.openBrowser().
 *
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer or Automated Animations needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const CONFIG = {
  weapon: "jb2a.melee_attack.01.shortsword.01", // any jb2a.melee_attack.* entry
  trail: "jb2a.melee_attack.01.trail.01.blueyellow", // null for no trail
  impact: "jb2a.impact.001.orange", // null for no impact
  impactScale: 1.3,
  blood: true,
  reachFt: 5, // targets further than this get the thrown fallback
  thrown: {
    go: "jb2a.dagger.throw.01.white",
    back: "jb2a.dagger.return.01.white"
  }, // null to always swing
  staggerMs: 700 // pause between targets
};

const attacker = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!attacker) return ui.notifications.warn("Select the attacking token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");

const missed = ["ShiftLeft", "ShiftRight"].some((code) => game.keyboard.downKeys.has(code));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Edge-to-edge distance in scene units, so large creatures are "in reach" like on the table. */
function gapInFeet(a, b) {
  const measured = canvas.grid.measurePath([a.center, b.center]).distance;
  const sizeBonus =
    ((Math.max(a.document.width, a.document.height) + Math.max(b.document.width, b.document.height)) / 2 - 1) *
    canvas.scene.grid.distance;
  return Math.max(0, measured - sizeBonus);
}

function addImpact(seq, target) {
  if (missed) return;
  if (CONFIG.impact) seq.effect().file(CONFIG.impact).atLocation(target).scaleToObject(CONFIG.impactScale).zIndex(3);
  if (CONFIG.blood) {
    seq
      .effect()
      .file("jb2a.liquid.splash_side.red")
      .atLocation(target)
      .rotateTowards(attacker)
      .rotate(180)
      .scaleToObject(1.5)
      .zIndex(2);
  }
}

const runs = [];
for (const target of targets) {
  const seq = SVA.sequence();
  const inReach = !CONFIG.thrown || gapInFeet(attacker, target) <= CONFIG.reachFt;

  if (inReach) {
    const flip = Math.random() < 0.5; // swing from either side for variety
    if (CONFIG.trail) {
      const trail = seq.effect().file(CONFIG.trail).atLocation(attacker).stretchTo(target).missed(missed).zIndex(1);
      if (flip) trail.mirrorY();
    }
    const swing = seq
      .effect()
      .file(CONFIG.weapon)
      .atLocation(attacker)
      .stretchTo(target)
      .missed(missed)
      .zIndex(2)
      .waitUntilFinished(-900);
    if (flip) swing.mirrorY();
  } else {
    seq.effect().file(CONFIG.thrown.go).atLocation(attacker).stretchTo(target).missed(missed).waitUntilFinished(-650);
  }

  addImpact(seq, target);
  if (!inReach) seq.effect().file(CONFIG.thrown.back).atLocation(attacker).stretchTo(target);

  runs.push(seq.play());
  await sleep(CONFIG.staggerMs);
}
await Promise.all(runs);
